<script setup lang="ts">
definePageMeta({ layout: 'public' }); const { data: meta } = await useAsyncData('public-meta-contact', () => $fetch<any>('/api/public/meta?route=/contact')); const { data: settings } = await useAsyncData('public-contact-settings', () => $fetch<any>('/api/public/settings')); const contactLabels = computed(() => settings.value?.data?.contact_form_labels || {}); const form = reactive({ name: '', email: '', phone: '', interest: '', message: '' }); const sent = ref(false); const pending = ref(false); useSeoMeta({ title: () => meta.value?.data.title, description: () => meta.value?.data.description }); async function submit() { pending.value = true; try { await $fetch('/api/public/contact', { method: 'POST', body: form }); sent.value = true; Object.assign(form, { name: '', email: '', phone: '', interest: '', message: '' }) } finally { pending.value = false } }
</script>
<template><div><PublicHero v-if="meta?.data" :meta="meta.data" /><PublicContentBlocks :blocks="meta?.data?.blocks" /><section class="mx-auto grid max-w-7xl gap-12 px-5 py-20 lg:grid-cols-12 sm:px-8"><div class="space-y-5 lg:col-span-5"><p class="text-sm uppercase tracking-[.2em] text-emerald-700">{{ settings?.data.contact_heading }}</p><p class="text-stone-600">{{ settings?.data.address }}</p><a class="block text-stone-600" :href="`tel:${settings?.data.phone}`">{{ settings?.data.phone }}</a><a class="block text-stone-600" :href="`mailto:${settings?.data.email}`">{{ settings?.data.email }}</a><iframe v-if="settings?.data.map_url" :title="meta?.data.title || ''" :src="settings.data.map_url" class="mt-8 h-64 w-full rounded-2xl border-0" loading="lazy" /></div><form class="space-y-5 rounded-2xl border border-stone-200 bg-white p-8 lg:col-span-7" @submit.prevent="submit"><Alert v-if="sent" variant="success" :message="contactLabels.success || ''" /><FormInput v-model="form.name" :label="contactLabels.name || ''" /><FormInput v-model="form.email" :label="contactLabels.email || ''" type="email" /><FormInput v-model="form.phone" :label="contactLabels.phone || ''" /><FormInput v-model="form.interest" :label="contactLabels.interest || ''" /><label class="block space-y-2 text-sm font-medium text-stone-700">{{ contactLabels.message }}<textarea v-model="form.message" required rows="5" class="w-full rounded-2xl border border-stone-200 bg-stone-50 px-4 py-3" /></label><FormButton :loading="pending">{{ contactLabels.submit }}</FormButton></form></section></div></template>